export const interval = 5000;
export const maxPollingSteps = 5;

/**
 * Poll for event updates that may not be available immediately after a payment operation.
 * When a property and action are provided, polling stops as soon as a matching event is received.
 */
export const usePollEvents = (propertyKey?: string, action?: EVENT_ACTIONS) => {
    const { call, subscribe } = useEventManager();

    const pollEventsMultipleTimes = async (
        propertyKeyOverride?: string,
        actionOverride?: EVENT_ACTIONS
    ): Promise<void> => {
        const expectedProperty = propertyKeyOverride ?? propertyKey;
        const expectedAction = actionOverride ?? action;
        const shouldSubscribe = expectedProperty !== undefined && expectedAction !== undefined;

        await new Promise<void>((resolve) => {
            let completed = false;
            let attempts = 0;
            let timeoutHandle: ReturnType<typeof setTimeout> | undefined;
            let unsubscribe: (() => void) | undefined;
            let didUnsubscribe = false;

            const unsubscribeOnce = () => {
                if (!unsubscribe || didUnsubscribe) {
                    return;
                }

                didUnsubscribe = true;
                try {
                    unsubscribe();
                } catch {
                    // Completion should not depend on a subscriber's cleanup implementation.
                }
            };

            const finish = () => {
                if (completed) {
                    return;
                }

                completed = true;
                if (timeoutHandle !== undefined) {
                    clearTimeout(timeoutHandle);
                    timeoutHandle = undefined;
                }
                unsubscribeOnce();
                resolve();
            };

            if (shouldSubscribe) {
                try {
                    const unsubscribeFromEvents = subscribe((event) => {
                        if (completed) {
                            return;
                        }

                        const updates = (event as unknown as Record<string, unknown>)[expectedProperty];
                        if (
                            Array.isArray(updates) &&
                            updates.some(
                                (update) =>
                                    update !== null &&
                                    typeof update === 'object' &&
                                    (update as { Action?: EVENT_ACTIONS }).Action === expectedAction
                            )
                        ) {
                            finish();
                        }
                    });
                    unsubscribe = unsubscribeFromEvents;
                    // A custom event manager may invoke the handler before subscribe returns.
                    if (completed) {
                        unsubscribeOnce();
                    }
                } catch {
                    // Polling still provides updates if subscribing is unavailable.
                }
            }

            if (completed) {
                return;
            }

            const poll = () => {
                if (completed) {
                    return;
                }

                attempts += 1;
                Promise.resolve()
                    .then(() => call())
                    .catch(() => undefined)
                    .then(() => {
                        if (completed) {
                            return;
                        }

                        if (attempts >= maxPollingSteps) {
                            finish();
                            return;
                        }

                        timeoutHandle = setTimeout(poll, interval);
                    });
            };

            timeoutHandle = setTimeout(poll, interval);
        });
    };

    return pollEventsMultipleTimes;
};
